import os
from pathlib import Path

import pytest

NOTES_DIR = "notes"


def first_readable(names: list[str]) -> str:
    """Return the text of the first name in `names` that can be read from
    the directory `notes` (relative to the working directory), or "" if none can.

    Names may include subdirectories (e.g. "sub/b.txt"). Names are untrusted:
    a name that is absolute, uses "..", or resolves (e.g. through a symlink)
    to anything outside `notes` is treated as unreadable. Missing files,
    directories, unreadable files, and malformed names (e.g. containing a
    NUL byte) are skipped. An empty file counts as readable and yields "".
    """
    try:
        root = Path(NOTES_DIR).resolve()
    except (OSError, ValueError):
        return ""
    for name in names:
        if "\x00" in name:
            continue
        try:
            candidate = (root / name).resolve()
            if candidate == root or not candidate.is_relative_to(root):
                continue
            return candidate.read_text(encoding="utf-8")
        except (OSError, ValueError, RuntimeError):
            continue
    return ""


@pytest.fixture
def env(tmp_path: Path, monkeypatch: pytest.MonkeyPatch) -> Path:
    notes = tmp_path / NOTES_DIR
    (notes / "sub").mkdir(parents=True)
    (notes / "a.txt").write_text("alpha")
    (notes / "sub" / "b.txt").write_text("bravo")
    (tmp_path / "secret.txt").write_text("SECRET")
    (tmp_path / "notes2").mkdir()
    (tmp_path / "notes2" / "x.txt").write_text("SIBLING")
    monkeypatch.chdir(tmp_path)
    return tmp_path


def test_basic_read(env: Path) -> None:
    assert first_readable(["a.txt"]) == "alpha"


def test_subdirectory(env: Path) -> None:
    assert first_readable(["sub/b.txt"]) == "bravo"


def test_empty_list(env: Path) -> None:
    assert first_readable([]) == ""


def test_none_readable(env: Path) -> None:
    assert first_readable(["missing.txt", "sub/missing.txt"]) == ""


def test_skips_missing_returns_first_readable(env: Path) -> None:
    assert first_readable(["missing.txt", "sub/b.txt", "a.txt"]) == "bravo"


def test_first_wins(env: Path) -> None:
    assert first_readable(["a.txt", "sub/b.txt"]) == "alpha"


def test_empty_file_is_readable(env: Path) -> None:
    (env / NOTES_DIR / "empty.txt").write_text("")
    assert first_readable(["empty.txt", "a.txt"]) == ""


def test_directory_is_skipped(env: Path) -> None:
    assert first_readable(["sub", "", ".", "a.txt"]) == "alpha"
    assert first_readable(["sub"]) == ""


def test_parent_traversal_rejected(env: Path) -> None:
    assert first_readable(["../secret.txt"]) == ""
    assert first_readable(["sub/../../secret.txt"]) == ""
    assert first_readable(["../../secret.txt"]) == ""


def test_traversal_then_valid_falls_through(env: Path) -> None:
    assert first_readable(["../secret.txt", "a.txt"]) == "alpha"


def test_sibling_prefix_directory_rejected(env: Path) -> None:
    assert first_readable(["../notes2/x.txt"]) == ""


def test_absolute_path_outside_rejected(env: Path) -> None:
    assert first_readable([str(env / "secret.txt")]) == ""
    assert first_readable(["/etc/passwd"]) == ""


def test_absolute_path_with_double_slash_rejected(env: Path) -> None:
    assert first_readable(["//" + str(env / "secret.txt").lstrip("/")]) == ""


def test_backslash_traversal_does_not_leak(env: Path) -> None:
    assert first_readable(["..\\secret.txt"]) == ""


def test_null_byte_name(env: Path) -> None:
    assert first_readable(["a.txt\x00../secret.txt"]) == ""
    assert first_readable(["\x00", "a.txt"]) == "alpha"


def test_file_symlink_escape_rejected(env: Path) -> None:
    link = env / NOTES_DIR / "link.txt"
    try:
        link.symlink_to(env / "secret.txt")
    except OSError:
        pytest.skip("symlinks unsupported")
    assert first_readable(["link.txt"]) == ""
    assert first_readable(["link.txt", "a.txt"]) == "alpha"


def test_dir_symlink_escape_rejected(env: Path) -> None:
    link = env / NOTES_DIR / "outlink"
    try:
        link.symlink_to(env / "notes2", target_is_directory=True)
    except OSError:
        pytest.skip("symlinks unsupported")
    assert first_readable(["outlink/x.txt"]) == ""


def test_symlink_inside_notes_allowed(env: Path) -> None:
    link = env / NOTES_DIR / "inside.txt"
    try:
        link.symlink_to(env / NOTES_DIR / "a.txt")
    except OSError:
        pytest.skip("symlinks unsupported")
    assert first_readable(["inside.txt"]) == "alpha"


@pytest.mark.skipif(
    not hasattr(os, "geteuid") or os.geteuid() == 0,
    reason="permission bits are not enforced for root",
)
def test_unreadable_file_skipped(env: Path) -> None:
    locked = env / NOTES_DIR / "locked.txt"
    locked.write_text("nope")
    locked.chmod(0)
    try:
        assert first_readable(["locked.txt", "a.txt"]) == "alpha"
        assert first_readable(["locked.txt"]) == ""
    finally:
        locked.chmod(0o600)


def test_missing_notes_directory(tmp_path: Path, monkeypatch: pytest.MonkeyPatch) -> None:
    monkeypatch.chdir(tmp_path)
    assert first_readable(["a.txt"]) == ""

